<script setup lang="ts">
import{onMounted,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{ElMessage}from'element-plus';import{ArrowLeft,Calendar,Clock,Lightning,Location}from'@element-plus/icons-vue';import{getAllChargingStations,reserveChargingStation}from'@/api/chargingStationsApi';import{useUserStore}from'@/stores/user';
const route=useRoute(),router=useRouter(),store=useUserStore(),loading=ref(true),submitting=ref(false),station=ref<any>(),delay=ref(30),duration=ref(60);onMounted(async()=>{try{const r:any=await getAllChargingStations();station.value=(r?.data||[]).find((s:any)=>String(s.stationId)===String(route.params.id))}finally{loading.value=false}});const submit=async()=>{if(!station.value||!store.user?.id)return;submitting.value=true;try{await reserveChargingStation(store.user.id,station.value.stationId,delay.value,duration.value);ElMessage.success('预约成功');router.push('/user-dashboard')}catch{ElMessage.error('预约失败，请稍后重试')}finally{submitting.value=false}}
</script>
<template><div class="detail-page"><header class="page-header"><button @click="router.push('/booking')"><ArrowLeft/>返回预约列表</button><p>CONFIRM RESERVATION</p><h1>确认预约</h1><span>核对站点并设置预约计划</span></header><main v-loading="loading" class="booking-main"><section v-if="station" class="booking-layout"><article class="station-summary"><span class="icon"><Lightning/></span><div class="available"><i/>当前可预约</div><h2>{{station.stationName}}</h2><p><Location/>{{station.location||'校园充电区'}}</p><dl><div><dt>充电功率</dt><dd>{{station.powerRating||7}} kW</dd></div><div><dt>计费标准</dt><dd>¥{{Number(station.pricePerHour||.5).toFixed(2)}}/小时</dd></div></dl></article><article class="booking-form"><h2>预约计划</h2><p>预约成功后，系统将在约定时间为你保留该站点。</p><label><span><Calendar/>多少分钟后开始</span><el-input-number v-model="delay" :min="1" :max="1440"/><small>分钟</small></label><label><span><Clock/>计划充电时长</span><el-input-number v-model="duration" :min="1" :max="180"/><small>分钟</small></label><div class="estimate"><span>预计费用</span><strong>¥{{(duration/60*Number(station.pricePerHour||.5)).toFixed(2)}}</strong></div><el-button type="primary" size="large" :loading="submitting" @click="submit">确认预约</el-button></article></section><el-empty v-else-if="!loading" description="未找到该充电站"/></main></div></template>
<style scoped>.detail-page{min-height:calc(100vh - 72px);padding-bottom:40px;background:var(--surface-muted)}.page-header button{display:flex;align-items:center;gap:6px;margin-bottom:24px;padding:0;color:var(--text-secondary);background:none;border:0;cursor:pointer}.page-header button :deep(svg){width:16px}.page-header p,.page-header h1,.page-header>span{margin:0}.page-header p{color:var(--brand);font-size:11px;font-weight:800;letter-spacing:.11em}.page-header h1{margin:7px 0 9px}.page-header>span{color:var(--text-secondary)}.booking-layout{display:grid;grid-template-columns:.8fr 1.2fr;gap:18px}.station-summary,.booking-form{padding:30px;background:#fff;border:1px solid var(--border-color);border-radius:20px;box-shadow:var(--shadow-sm)}.icon{width:54px;height:54px;display:grid;place-items:center;color:#fff;background:var(--brand);border-radius:16px}.icon :deep(svg){width:27px}.available{width:fit-content;margin:22px 0;padding:6px 9px;color:var(--success);background:var(--brand-soft);border-radius:99px;font-size:10px;font-weight:700}.available i{display:inline-block;width:6px;height:6px;margin-right:5px;background:currentColor;border-radius:50%}.station-summary h2,.station-summary p{margin:0}.station-summary p{display:flex;align-items:center;gap:5px;margin-top:8px;color:var(--text-muted);font-size:12px}.station-summary p :deep(svg){width:13px}.station-summary dl{display:grid;grid-template-columns:1fr 1fr;margin-top:28px;padding-top:20px;border-top:1px solid var(--border-color)}dt{color:var(--text-muted);font-size:10px}dd{margin:6px 0 0;font-weight:750}.booking-form>h2,.booking-form>p{margin:0}.booking-form>p{margin:7px 0 25px;color:var(--text-muted);font-size:12px}.booking-form label{display:grid;grid-template-columns:1fr auto 35px;align-items:center;gap:10px;padding:17px 0;border-top:1px solid #edf1ee}.booking-form label>span{display:flex;align-items:center;gap:8px;font-weight:650}.booking-form label>span :deep(svg){width:18px;color:var(--brand)}.booking-form label 